"""Conditional on invariant layer cut, no bridge matching supplied. Enumerate correlated layer relabelings, unmarked pair orbits and a static relative-incidence readout."""
from ramsey38_unmarked_frame import P,W,V,side,key,D,json,it
L=sorted(side);R=sorted(V-side);G=set(P.values());H=[g for g in G if g[L[0]] in L];assert all({g[i] for i in L}==set(L) for g in H);proj=lambda U:{tuple(g[i] for i in U) for g in H};cross={key(i,j) for i in L for j in R};orbit=lambda G,e:frozenset(key(g[e[0]],g[e[1]]) for g in G);parts=lambda G:{orbit(G,e) for e in cross};Q=sorted(parts(G),key=lambda q:min(q));match=lambda q:len({i for e in q for i in e})==2*len(q)==8
